from collections import defaultdict

def count_Substrings(s):
    n = len(s)
    count = 0
    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += ord(s[j]) - ord('0')
            if current_sum == j - i + 1:
                count += 1
    return count

